#!/usr/bin/env python
"""Take a snapshot of all running tqdm bars for debugging purposes."""
import sys
from os import path

sys.path.insert(0, path.dirname(path.dirname(path.abspath(__file__))))

from tqdm import tqdm  # noqa: E402


def main():
    """Print a snapshot of all active tqdm instances."""
    for inst in sorted(tqdm._instances):
        print(inst)


if __name__ == '__main__':
    main()

